update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p111","body":"تم سے بچھڑ کے میں ، آخر  سنبھل  گیا ہوں\nاک بار پھر کچے آسرے سے ٹل  گیا ہوں\nیہ جانتے ہوئے کہ تم کیا خاک سنبھالو گے\nٹوٹا سا دل مرا پھر سے توڑ ڈالو گے\nمیں نے تم پہ یقین کر لیا تھا\nخود خسارہ اپنے سر لیا تھا\nتم کہ جھونکتے رہے دھول آنکھوں میں\nہم نے رواں رکھا تمہیں اپنی سانسوں میں\nخیر اس میں میرا ہی قصور ہے\nمجھ سے وفا بہت دور ہے\nمیں نے ہی تو تمہیں اس آزمائش میں ڈالا تھا\nہمیشہ زمانے کی گردشوں سے سنبھالا تھا\nمجھے یوں مخلص نہیں ہونا چاہیے تھا\nیوں تم سا شخص نہیں کھونا چایئے تھا\nپر تم جانتی ہو میں کبھی سوال  نہیں رکھتا\nدل میں کوئی بھی  ملال نہیں رکھتا\nجانتا ہوں تمارے جواب پہلے سے\nدل پہ اترتا رہا ہے یہ عذاب پہلے سے\nپھر سے کر کے اندھا اعتماد ، میں بہل جاوں گا\nاس بار بھی پہلے کی طرح  میں سنبھل جاوں گا\nخوش رہنا ، تم میری فکر مت کرنا\nکسی کے سامنے میرا زکر مت کرنا\nاپنی زندگی کو گزارنا نہیں بلکہ جیون کرنا\nاک طرف رہنا، کسی کی زندگی نہ اجیرن کرنا\nمیں آئندہ دو دلوں کے بیچ نہیں آوں گا\nمیں اب امید ہے یہ بات جان جاوں گا\nجان جاوں گا یہ خسارے کہاں سے آتے ہیں\nہم گرنے والوں کو سہارے کہاں سے آتے ہیں؟"},{"slug":"tum-p112","body":"ترکِ تعلق پہ کہیں پیچ و خم بھی نہیں\nتم سے میں ذرا برہم بھی نہیں\n\nکہیں محبت کی لُو چلتی رہی\nکہیں ستم کا یہ عالم بھی نہیں\n\nتیرے شہر سے نکلے ہیں اس طرح سے ہم\nکہ پلٹ کے جانے کے مراسم بھی نہیں\n\nتم سے دور رہا ہوں تو یہ لگتا ہے\nتمہارے سوا کوئی دوسرا غم بھی نہیں\n\nکبھی بس تم ہی کا انتظار یے\nکبھی لگتا ہے کہ تم بھی نہیں"},{"slug":"tum-p113","body":"تم سے رہی دوری ، کہنے کو رابطے رہے\nوہ سڑک نہ رہی پر وہ راستے رہے\n\nتھمادیں وفائیں جس نے جتنی چاہیں\nاپنے حصے میں سب درد ہی بانٹتے رہے\n\nہم نہ ہوئے پھر ان میں شامل اگرچہ\nتمہیں لوگ بلاتے رہے ، لوگ چاہتے رہے\n\nہم نے لکھی فقط تمہارے لیے رمز احمد ؔ\nیوں بہت لوگ سنتے رہے ، ہم سناتے رہے"},{"slug":"tum-p114","body":"جسے ابھی سلام کیا ہے\nوہ شہر چھوڑ گیا ہے\n\nملنے کی بات نہ ہی کرو\nپہلے کونسا کوئی ملا ہے\n\nجوں جوں اندھیرا ہو رہا ہے\nگھر کا رستہ بھول رہا ہے\n\nہجوم میں کھڑا یہ شخص\nخود ہی خود میں گم چکا ہے\n\nکوئی تو رہتا ہے ویرانیوں میں\nپلٹ کے نام جو گونج رہا ہے\n\nکعبے میں کچھ نہیں رکھا\nاحمد ؔ دل ہی اگر خالی پڑا ہے"},{"slug":"tum-p115","body":"تیری یاد جب آتی ہے\nنیند اڑ سی جاتی ہے\n\nخواب ٹوٹتے بُنتے رہتے ہیں\nشمع جلتی بجھتی جاتی ہے\n\nکھڑکیوں کے کناروں سے  کٹ کر\nچاندنی کمرے میں جھانک آتی ہے\n\nجب کبھی انگن پہ دستک ہوتی ہے\nتیرے لمس کی محک آتی ہے\n\nدرد دل کی سب کہانیوں میں\nتیری جھلک نظر آتی ہے\n\nاحمد ؔ ہمیں تو اس کی یاد آتی ہے\nاسے کیا چیز رات جگاتی ہے"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
